(1357, '2023-01-25 12:40:07', 89, 'EMT', '', 'One of the pin for wafer clamp was found damaged. A new one made from workshop.\\r\\nAdjustment of the loading arm done.\\r\\nAfter that checked loading / unloading checked, working fine at room temperature.\\r\\nAs discussed with FIC, loading unloading above 100degC should not be done till further notice.', 'Vinayak, Pradeep', '', '', '', '', '', '', '', '0000-00-00 00:00:00', '', '', '', ''),
(1360, '2023-01-25 13:10:18', 89, 'EMT', 'EMT did troubleshooting and found the Y-stage movement screw gauge is not working', 'The Y-stage movement is having threads damaged.\\r\\nOpened and checked the same, it cannot be repaired.\\r\\nNeed to order new one.\\r\\n', '', '', '', '', '', '', '', '', '0000-00-00 00:00:00', 'Email sent to vendor for new quote.', '', 'uploads/1360_0.jpeg', ''),
