INSERT INTO `trouble_track` (`complaint_id`, `timestamp`, `status_mark_by`, `working_team`, `diagnosis`, `action_taken`, `work_done_by`, `vendor_name`, `vendor_contact`, `vendor_interaction`, `vendor_comments`, `spare_parts`, `cost_spare_parts`, `procurement_time_spares`, `expected_completion_date`, `action_plan`, `action_item_owner`, `file`, `comments`) VALUES
(2866, '2026-01-01 15:02:50', 2457, 'EMT and Facility', 'after preventive maintenance of the AHU and Chiller, water flushing need to be done of the tool                                                                                                                                                                 .', '1. System was already turned off the SO, so after PM work of AHU and Chiller was complete, we started with the water line flushing.\\r\\n2. Raj from facility turned off the inlet and outlet valves of the water line connection.\\r\\n3. we removed inlet and outlet water connection one by one from total 5 water connections.\\r\\n4. With CDA connections, apply cda flow to inlet side and water flush the line from tool side through outlet side.\\r\\n5. repeated same steps with other water line connections.\\r\\n6. Completed the water line flushing, told facility member raj to open the both outlet first and then inlet water valves.\\r\\n7. After water flushing, hemant sir turned on the tool.', 'Avinash and Rhifa (EMT) and Raj (Facility)', '', '', '', '', '', '', '', '', '', '', '', ''),
(2890, '2026-01-01 15:19:01', 2521, 'Electrical facility', 'Planned preventive maintenance -\\r\\nUPS daily reading for NANO 1 UPS, New Building UPS 1, New Building UPS 2, MICRO UPS output load (%VA) ,System temperature (TS), Rectifier temperature(TR), Invertor temperature(TI) to be updated in electrical facility reading log.', 'UPS daily reading for NANO 1 UPS, New Building UPS 1, New Building UPS 2, MICRO UPS output load (%VA) ,System temperature (TS), Rectifier temperature(TR), Invertor temperature(TI) updated in electrical facility reading log.', 'Sanjay', '', '', '', '', 'NA', 'NA', 'NA', '', 'UPS daily reading for NANO 1 UPS, New Building UPS 1, New Building UPS 2, MICRO UPS output load (%VA) ,System temperature (TS), Rectifier temperature(TR), Invertor temperature(TI)  updated in log.', 'Swapnil', 'uploads/2890_0.pptx', 'New building UPS 1 Rectifier temperature(TR), Invertor temperature(TI)  increased by 2 degree Celsius, safe limit is below 40 degree Celsius. needs to do UPS servicing.'),
(2865, '2026-01-01 16:54:16', 2457, 'EMT and Facility', 'after ahu and chiller pm work complete by facility team, did water line flushing                                                                                                                                                                            .', '1. System was already turned off by the SO. 2. So after PM work of AHU and Chiller was complete, we started with the water line flushing. 3. Amit sir from facility turned off the inlet and outlet valves of the water line connection. 4. we removed inlet and outlet water line connection . 5. With CDA connection, apply cda flow to inlet side and water flush the line from tool side through outlet side.rn5. Completed the water line flushing, told facility member raj to open the both outlet first and then inlet water valves.rn7. After water flushing, hemant sir turned on the tool.', 'Avinash and Rhifa(EMT) and Amit ji (Facility)', '', '', '', '', '', '', '', '', '', '', '', ''),
(2838, '2026-01-01 16:57:52', 2378, '', 'Proxima tools cleaning is done with lint free clothes. Too much dust is observed. Proxima , Polaris and Rigel computer table and behind PC cleaning is done . consumables are kept in stock and monitored daily.', 'Proxima tools cleaning is done with lint free clothes. Too much dust is observed. Proxima , Polaris and Rigel computer table and behind PC cleaning is done . consumables are kept in stock and monitored daily.', '', '', '', '', '', '', '', '', '', '', '', 'uploads/2838_0.pdf', ''),
